func splitFlow(s string) []string {
        parts := []string{}
        depth := 0
        inSingle := false
        inDouble := false
        start := 0
        for i := 0; i < len(s); i++ {
                c := s[i]
                switch c {
                case '\'':
                        if !inDouble {
                                inSingle = !inSingle
                        }
                case '"':
                        if !inSingle {
                                inDouble = !inDouble
                        }
                case '[', '{':
                        if !inSingle && !inDouble {
                                depth++
                        }
                case ']', '}':
                        if !inSingle && !inDouble {
                                depth--
                        }
                case ',':
                        if depth == 0 && !inSingle && !inDouble {
                                parts = append(parts, s[start:i])
                                start = i + 1
                        }
                }
        }
        parts = append(parts, s[start:])
        return parts
}
